create table constitution.decision_explanation_factors (id uuid primary key default gen_random_uuid(),recommendation_id uuid not null references constitution.decision_recommendations(id) on delete cascade,factor_type text not null,factor_name text not null,direction text not null,importance numeric(6,5) not null,explanation text not null,evidence_refs jsonb not null default '[]'::jsonb,uncertainty numeric(6,5) not null default 0,created_at timestamptz not null default now(),check(factor_type in ('objective','risk','constraint','evidence','assumption','sensitivity','dissent')),check(direction in ('supports','opposes','neutral','conditional')),check(importance between 0 and 1),check(uncertainty between 0 and 1));
create table constitution.decision_sensitivity_findings (id uuid primary key default gen_random_uuid(),recommendation_id uuid not null references constitution.decision_recommendations(id) on delete cascade,variable_name text not null,baseline_value jsonb not null default 'null'::jsonb,tested_range jsonb not null default '{}'::jsonb,impact_score numeric(6,5) not null,switch_threshold jsonb not null default '{}'::jsonb,would_change_recommendation boolean not null default false,explanation text not null,created_at timestamptz not null default now(),check(impact_score between 0 and 1));
create table constitution.decision_explainability_audit (id uuid primary key default gen_random_uuid(),recommendation_id uuid not null references constitution.decision_recommendations(id) on delete cascade,event_type text not null,actor text,event_payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index idx_decision_requests_experiment on constitution.decision_intelligence_requests(experiment_id);
create index idx_decision_recommendations_experiment on constitution.decision_recommendations(experiment_id);
create index idx_decision_option_recommendation on constitution.decision_option_assessments(recommendation_id,rank);
create index idx_decision_factors_recommendation on constitution.decision_explanation_factors(recommendation_id,importance desc);
create index idx_decision_sensitivity_recommendation on constitution.decision_sensitivity_findings(recommendation_id,impact_score desc);